INSERT INTO educations (id, year_th, degree, institute, sort_order, deleted_at) VALUES (1, 2563, 'ศึกษาศาสตรมหาบัณฑิต (ศษ.ม.) สาขาหลักสูตรและการสอน', 'มหาวิทยาลัยเชียงใหม่', 1, NULL);
INSERT INTO educations (id, year_th, degree, institute, sort_order, deleted_at) VALUES (2, 2557, 'ครุศาสตรบัณฑิต (ค.บ.) สาขาคอมพิวเตอร์ศึกษา เกียรตินิยมอันดับ 2', 'มหาวิทยาลัยราชภัฏเชียงใหม่', 2, NULL);
INSERT INTO career_paths (id, period, position, school, is_current, sort_order, deleted_at) VALUES (1, '2557 – 2559', 'ครูผู้ช่วย', 'โรงเรียนบ้านห้วยน้ำใส', 0, 1, NULL);
INSERT INTO career_paths (id, period, position, school, is_current, sort_order, deleted_at) VALUES (2, '2559 – 2565', 'ครู (คศ.1)', 'โรงเรียนบ้านสวนดอกไม้', 0, 2, NULL);
INSERT INTO career_paths (id, period, position, school, is_current, sort_order, deleted_at) VALUES (3, '2565 – ปัจจุบัน', 'ครูชำนาญการ (คศ.2)', 'โรงเรียนบ้านสวนดอกไม้', 1, 3, NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (1, 1, 'พัฒนาหลักสูตรรายวิชาเพิ่มเติม “วิทยาการคำนวณและปัญญาประดิษฐ์เบื้องต้น”', 'พัฒนาหลักสูตรรายวิชาเพิ่มเติม-วิทยาการคำนวณและปัญญาประดิษฐ์', 'ยกร่างและพัฒนาหลักสูตรรายวิชาเพิ่มเติม 40 ชั่วโมง/ปี ผ่านการพิจารณาจากคณะกรรมการบริหารหลักสูตรสถานศึกษา', '<h3>ที่มาและความสำคัญ</h3><p>จากการวิเคราะห์หลักสูตรสถานศึกษาพบว่ารายวิชาพื้นฐานวิทยาการคำนวณมีเวลาเรียนจำกัด ไม่เพียงพอต่อการพัฒนาสมรรถนะด้านปัญญาประดิษฐ์ซึ่งเป็นทักษะจำเป็นของผู้เรียนในศตวรรษที่ 21</p><h3>ขั้นตอนดำเนินการ</h3><p>ศึกษามาตรฐานการเรียนรู้และตัวชี้วัดกลุ่มสาระวิทยาศาสตร์และเทคโนโลยี วิเคราะห์ความต้องการจำเป็นของผู้เรียน 128 คน ยกร่างโครงสร้างรายวิชา 40 ชั่วโมง จัดทำคำอธิบายรายวิชา หน่วยการเรียนรู้ 5 หน่วย และเกณฑ์การวัดประเมินผล จากนั้นนำเสนอต่อคณะกรรมการบริหารหลักสูตรสถานศึกษาเพื่อพิจารณา และปรับปรุงตามข้อเสนอแนะ</p><h3>ผลที่เกิดกับผู้เรียน</h3><p>ผู้เรียนได้เรียนรู้เนื้อหาปัญญาประดิษฐ์เบื้องต้นอย่างเป็นระบบ ร้อยละ 92 ผ่านเกณฑ์การประเมินสมรรถนะการคิดเชิงคำนวณระดับดีขึ้นไป และหลักสูตรได้รับความเห็นชอบให้ใช้จริงในปีการศึกษา 2569</p>', 2569, 1, '2026-05-18', 'static', 'media/seed/w1_1.jpg', '', 'หลักสูตร,AI,วิทยาการคำนวณ,หลักสูตรสถานศึกษา', 214, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (2, 1, 'ปรับปรุงหน่วยการเรียนรู้ “Digital Literacy” ให้สอดคล้องหลักสูตรสถานศึกษา ปี 2569', 'ปรับปรุงหน่วยการเรียนรู้-digital-literacy', 'ปรับปรุงหน่วยการเรียนรู้ 2 หน่วย เพิ่มเนื้อหาการรู้เท่าทันสื่อและความปลอดภัยไซเบอร์ พร้อมผังมโนทัศน์', '<h3>สภาพปัญหา</h3><p>ผลการประเมินภายในปีที่ผ่านมาพบว่านักเรียนยังขาดทักษะการตรวจสอบความน่าเชื่อถือของข้อมูลออนไลน์ และตกเป็นเหยื่อข่าวปลอมบ่อยครั้ง</p><h3>การดำเนินการ</h3><p>วิเคราะห์ตัวชี้วัดที่เกี่ยวข้อง ปรับคำอธิบายหน่วยการเรียนรู้ 2 หน่วย เพิ่มสาระการรู้เท่าทันสื่อ (Media Literacy) และความปลอดภัยไซเบอร์ ออกแบบผังมโนทัศน์ (Concept Map) และกำหนดชิ้นงาน/ภาระงานประจำหน่วยใหม่</p><h3>ผลที่เกิดขึ้น</h3><p>คะแนนแบบทดสอบการรู้เท่าทันสื่อหลังเรียนเพิ่มขึ้นจากค่าเฉลี่ย 12.4 เป็น 17.8 คะแนน (เต็ม 20) หน่วยการเรียนรู้ถูกนำไปใช้ร่วมกันทั้งกลุ่มสาระ</p>', 2568, 2, '2026-02-11', 'static', 'media/seed/w2_1.jpg', '', 'หลักสูตร,รู้เท่าทันสื่อ,Digital Literacy', 138, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (3, 2, 'ห้องเรียนกลับด้าน (Flipped Classroom) หน่วย “อัลกอริทึมใกล้ตัว”', 'ห้องเรียนกลับด้าน-อัลกอริทึมใกล้ตัว', 'ออกแบบการจัดการเรียนรู้แบบห้องเรียนกลับด้าน ผู้เรียนดูวิดีโอล่วงหน้า ใช้เวลาในห้องเรียนลงมือปฏิบัติจริง', '<h3>แนวคิดการออกแบบ</h3><p>ใช้รูปแบบ Flipped Classroom ร่วมกับการเรียนรู้แบบร่วมมือ (Cooperative Learning) เพื่อเพิ่มเวลาในการลงมือปฏิบัติและให้คำแนะนำรายบุคคลในชั้นเรียน</p><h3>ขั้นตอนดำเนินการ</h3><p>ผลิตวิดีโอสั้น 8 คลิป คลิปละ 5–7 นาที เผยแพร่ผ่าน Google Classroom ให้นักเรียนศึกษาล่วงหน้า พร้อมแบบตรวจสอบความเข้าใจก่อนเข้าเรียน เวลาในห้องเรียนใช้ทำกิจกรรมกลุ่ม เขียนผังงาน และแก้โจทย์สถานการณ์จริง ครูทำหน้าที่เป็นผู้อำนวยความสะดวก</p><h3>ผลที่เกิดกับผู้เรียน</h3><p>เวลาปฏิบัติกิจกรรมในห้องเรียนเพิ่มขึ้นร้อยละ 60 นักเรียนบรรลุจุดประสงค์การเรียนรู้ร้อยละ 88 และมีความพึงพอใจต่อรูปแบบการสอนเฉลี่ย 4.62 จาก 5</p>', 2569, 1, '2026-06-24', 'static', 'media/seed/w3_1.jpg', '', 'Flipped Classroom,อัลกอริทึม,ป.5,Active Learning', 245, 1, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (4, 2, 'แผนการจัดการเรียนรู้เชิงรุก (Active Learning) 20 แผน ภาคเรียนที่ 1', 'แผนการจัดการเรียนรู้เชิงรุก-20-แผน', 'จัดทำแผนการจัดการเรียนรู้เชิงรุกครบ 20 แผน ผ่านการนิเทศจากหัวหน้ากลุ่มสาระและฝ่ายวิชาการ', '<h3>วัตถุประสงค์</h3><p>เพื่อจัดทำแผนการจัดการเรียนรู้ที่เน้นผู้เรียนเป็นสำคัญ สอดคล้องกับมาตรฐานและตัวชี้วัด พร้อมสอดแทรกสมรรถนะสำคัญของผู้เรียน</p><h3>การดำเนินการ</h3><p>วิเคราะห์ตัวชี้วัดและสาระการเรียนรู้แกนกลาง ออกแบบแผนตามรูปแบบ 5E ผสมผสานเทคนิค Think–Pair–Share, Gallery Walk และ Problem-based Learning จัดทำสื่อและใบงานประกอบทุกแผน รับการนิเทศและปรับปรุงตามข้อเสนอแนะ</p><h3>ผลลัพธ์</h3><p>แผนทั้ง 20 แผนผ่านการนิเทศระดับดีมาก นักเรียนบรรลุจุดประสงค์การเรียนรู้เฉลี่ยร้อยละ 85.6</p>', 2569, 1, '2026-05-30', 'static', 'media/seed/w4_1.jpg', '', 'Active Learning,แผนการสอน,5E', 176, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (5, 3, 'กิจกรรม Unplugged Coding “เกมถอดรหัสลับ” 8 สัปดาห์', 'กิจกรรม-unplugged-coding-เกมถอดรหัสลับ', 'จัดกิจกรรมการเรียนรู้แบบไม่ใช้คอมพิวเตอร์ ฝึกการคิดเชิงคำนวณผ่านเกมและบัตรคำสั่ง 8 สัปดาห์ต่อเนื่อง', '<h3>ที่มา</h3><p>นักเรียนบางส่วนขาดโอกาสเข้าถึงคอมพิวเตอร์ที่บ้าน จึงออกแบบกิจกรรม Unplugged Coding ให้ทุกคนได้ฝึกคิดเชิงคำนวณอย่างเท่าเทียม</p><h3>ขั้นตอน</h3><p>สัปดาห์ที่ 1–2 ทำความรู้จักลำดับขั้นตอน (Sequence) ผ่านเกมหุ่นยนต์เดินตามคำสั่ง สัปดาห์ที่ 3–4 การวนซ้ำ (Loop) ด้วยเกมเต้นตามจังหวะ สัปดาห์ที่ 5–6 เงื่อนไข (Condition) ด้วยเกมถอดรหัสลับ สัปดาห์ที่ 7–8 บูรณาการสร้างเกมของตนเองและนำเสนอ</p><h3>ผลที่เกิดกับผู้เรียน</h3><p>คะแนนแบบวัดการคิดเชิงคำนวณเพิ่มขึ้นเฉลี่ยร้อยละ 28.3 นักเรียนกลุ่มอ่อนมีพัฒนาการสูงสุด และร้อยละ 97 ระบุว่ากิจกรรมสนุกและอยากเรียนต่อ</p>', 2569, 1, '2026-06-05', 'static', 'media/seed/w5_1.jpg', '', 'Unplugged,Coding,การคิดเชิงคำนวณ,เกม', 198, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (6, 3, 'ค่าย Robot & Coding Camp บูรณาการสะเต็มศึกษา', 'ค่าย-robot-coding-camp-สะเต็มศึกษา', 'จัดค่ายเชิงปฏิบัติการ 2 วัน 1 คืน นักเรียน 60 คน บูรณาการวิทยาศาสตร์ เทคโนโลยี วิศวกรรม และคณิตศาสตร์', '<h3>วัตถุประสงค์</h3><p>เพื่อให้นักเรียนได้ประยุกต์ความรู้ข้ามกลุ่มสาระผ่านการแก้ปัญหาจริงด้วยกระบวนการออกแบบเชิงวิศวกรรม</p><h3>กิจกรรม</h3><p>ฐานที่ 1 ประกอบหุ่นยนต์เดินตามเส้น ฐานที่ 2 เขียนโปรแกรมควบคุมด้วย micro:bit ฐานที่ 3 ออกแบบสะพานรับน้ำหนัก ฐานที่ 4 การแข่งขันภารกิจกู้ภัย ปิดค่ายด้วยการนำเสนอผลงานและถอดบทเรียน</p><h3>ผลลัพธ์</h3><p>นักเรียน 60 คนผ่านเกณฑ์การประเมินทักษะกระบวนการออกแบบเชิงวิศวกรรมร้อยละ 90 มีทีมได้รับคัดเลือกไปแข่งขันระดับเขตพื้นที่ 2 ทีม</p>', 2568, 2, '2026-01-24', 'static', 'media/seed/w6_1.jpg', '', 'STEM,หุ่นยนต์,ค่าย,microbit', 167, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (7, 4, 'สื่อ AR “ระบบสุริยะ” สแกนเล่นได้จริงในห้องเรียน', 'สื่อ-ar-ระบบสุริยะ', 'พัฒนาสื่อความจริงเสริม (Augmented Reality) ประกอบหน่วยดาราศาสตร์ นักเรียนสแกน marker เห็นดาวเคราะห์สามมิติ', '<h3>🎯 วัตถุประสงค์</h3><p>เพื่อพัฒนาสื่อความจริงเสริม (Augmented Reality) ประกอบหน่วยการเรียนรู้ดาราศาสตร์ ให้นักเรียนเห็นภาพดาวเคราะห์แบบสามมิติ เข้าใจขนาด ระยะทาง และการโคจรได้ชัดเจนขึ้น แก้ปัญหาการจินตนาการเนื้อหานามธรรมไม่ออก</p><h3>🛠️ ขั้นตอนดำเนินการ</h3><p>ออกแบบ marker ประจำดาวเคราะห์ทั้ง 8 ดวง สร้างโมเดลสามมิติด้วยโปรแกรมโอเพนซอร์ส ทดลองใช้กับนักเรียน 32 คน พร้อมใบกิจกรรม “นักสำรวจอวกาศน้อย” และแบบวัดผลก่อน–หลังเรียน จากนั้นปรับปรุงตามข้อเสนอแนะของนักเรียนและครูพี่เลี้ยง</p><h3>🌟 ผลที่เกิดกับผู้เรียน</h3><p>คะแนนเฉลี่ยหลังเรียนเพิ่มขึ้นร้อยละ 31.4 นักเรียนร้อยละ 96 ระบุว่าสนุกและอยากเรียนด้วยสื่อ AR อีก ผลงานได้รับคัดเลือกนำเสนอในเวที PLC ระดับเขตพื้นที่</p>', 2569, 1, '2026-06-12', 'static', 'media/seed/w7_1.jpg', '', 'AR,ดาราศาสตร์,สื่อนวัตกรรม,ป.5', 312, 1, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (8, 4, 'เว็บแอปฝึกพิมพ์สัมผัสภาษาไทย “KruKom Typing”', 'เว็บแอปฝึกพิมพ์สัมผัส-krukom-typing', 'พัฒนาเว็บแอปฝึกพิมพ์สัมผัสภาษาไทยพร้อมระบบเก็บสถิติรายบุคคล ใช้งานได้ทั้งคอมพิวเตอร์และแท็บเล็ต', '<h3>สภาพปัญหา</h3><p>นักเรียนพิมพ์ภาษาไทยด้วยวิธีจิ้มดีด ทำให้เสียเวลาและเกิดข้อผิดพลาดสูงเมื่อต้องทำชิ้นงานดิจิทัล</p><h3>การพัฒนา</h3><p>พัฒนาเว็บแอปด้วย HTML/CSS/JavaScript แบ่งบทเรียนเป็น 12 ระดับ มีระบบจับเวลา นับคำต่อนาที (WPM) คำนวณความแม่นยำ และบันทึกสถิติรายบุคคล ครูดูภาพรวมชั้นเรียนผ่านหน้าแดชบอร์ด</p><h3>ผลการใช้</h3><p>หลังใช้ 10 สัปดาห์ ความเร็วเฉลี่ยเพิ่มจาก 12 เป็น 27 คำ/นาที ความแม่นยำเพิ่มจากร้อยละ 78 เป็น 94</p>', 2569, 1, '2026-06-28', 'static', 'media/seed/w8_1.jpg', '', 'เว็บแอป,พิมพ์สัมผัส,นวัตกรรม,JavaScript', 189, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (9, 5, 'แบบวัดสมรรถนะการคิดเชิงคำนวณ พร้อมเกณฑ์รูบริก 5 ระดับ', 'แบบวัดสมรรถนะการคิดเชิงคำนวณ-รูบริก', 'สร้างเครื่องมือวัดสมรรถนะการคิดเชิงคำนวณ 4 องค์ประกอบ ผ่านการตรวจ IOC จากผู้เชี่ยวชาญ 5 ท่าน', '<h3>กระบวนการสร้างเครื่องมือ</h3><p>ศึกษาแนวคิดการคิดเชิงคำนวณของ Wing (2006) กำหนดองค์ประกอบ 4 ด้าน ได้แก่ การแยกส่วนประกอบ การจดจำรูปแบบ การคิดเชิงนามธรรม และการออกแบบอัลกอริทึม</p><h3>การตรวจสอบคุณภาพ</h3><p>สร้างข้อคำถาม 32 ข้อ ตรวจความตรงเชิงเนื้อหาโดยผู้เชี่ยวชาญ 5 ท่าน ได้ค่า IOC ระหว่าง 0.80–1.00 ทดลองใช้กับนักเรียนที่ไม่ใช่กลุ่มตัวอย่าง 40 คน ได้ค่าความเชื่อมั่น (KR-20) เท่ากับ 0.86</p><h3>การนำไปใช้</h3><p>ใช้เป็นเครื่องมือวัดก่อน–หลังเรียนของประเด็นท้าทาย และนำผลไปวางแผนการสอนซ่อมเสริมรายบุคคล</p>', 2568, 2, '2026-02-27', 'static', 'media/seed/w9_1.jpg', '', 'รูบริก,การวัดผล,การคิดเชิงคำนวณ,IOC', 156, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (10, 5, 'คลังข้อสอบออนไลน์ วิเคราะห์คุณภาพข้อสอบด้วย Google Forms + Sheets', 'คลังข้อสอบออนไลน์-วิเคราะห์ข้อสอบ', 'จัดทำคลังข้อสอบ 300 ข้อ พร้อมสูตรวิเคราะห์ค่าความยากง่ายและอำนาจจำแนกอัตโนมัติ', '<h3>แนวคิด</h3><p>ลดภาระงานเอกสารและเพิ่มคุณภาพเครื่องมือวัดผล ด้วยการวิเคราะห์ข้อสอบอัตโนมัติทุกครั้งที่สอบ</p><h3>การดำเนินการ</h3><p>จัดหมวดหมู่ข้อสอบตามตัวชี้วัดและระดับพฤติกรรมตามแนวคิดของ Bloom สร้างสูตรใน Google Sheets คำนวณค่าความยากง่าย (p) และค่าอำนาจจำแนก (r) พร้อมแสดงผลเป็นแดชบอร์ด</p><h3>ผลที่ได้</h3><p>คัดข้อสอบที่มีคุณภาพตามเกณฑ์ (p ระหว่าง 0.20–0.80, r ≥ 0.20) ไว้ 246 ข้อ นำไปใช้ในการสอบกลางภาคและปลายภาค</p>', 2569, 1, '2026-07-01', 'static', 'media/seed/w10_1.jpg', '', 'ข้อสอบ,การวัดผล,Google Forms', 0, 0, 'draft', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (11, 6, 'วิจัยในชั้นเรียน: แก้ปัญหาการลำดับขั้นตอนการแก้ปัญหาด้วยบอร์ดเกม', 'วิจัยในชั้นเรียน-บอร์ดเกม-ลำดับขั้นตอน', 'วิจัยเชิงปฏิบัติการในชั้นเรียน กลุ่มเป้าหมาย 32 คน ใช้บอร์ดเกมเป็นนวัตกรรมแก้ปัญหา', '<h3>ปัญหาการวิจัย</h3><p>จากการสังเกตและตรวจใบงานพบว่า นักเรียนร้อยละ 42 ไม่สามารถลำดับขั้นตอนการแก้ปัญหาอย่างเป็นระบบได้</p><h3>ระเบียบวิธีวิจัย</h3><p>วิจัยเชิงปฏิบัติการในชั้นเรียน (Classroom Action Research) 2 วงรอบ กลุ่มเป้าหมาย 32 คน เครื่องมือคือบอร์ดเกม “เส้นทางนักคิด” แบบวัดการคิดเชิงคำนวณ และแบบสังเกตพฤติกรรม วิเคราะห์ข้อมูลด้วยค่าเฉลี่ย ส่วนเบี่ยงเบนมาตรฐาน และ t-test แบบ dependent</p><h3>ผลการวิจัย</h3><p>คะแนนหลังเรียนสูงกว่าก่อนเรียนอย่างมีนัยสำคัญทางสถิติที่ระดับ .05 (t = 9.34) จำนวนนักเรียนที่ลำดับขั้นตอนไม่ได้ลดจากร้อยละ 42 เหลือร้อยละ 9</p>', 2568, 2, '2026-03-06', 'static', 'media/seed/w11_1.jpg', '', 'วิจัยในชั้นเรียน,บอร์ดเกม,CAR', 176, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (12, 6, 'การศึกษาผลของการใช้ Scratch ต่อความคิดสร้างสรรค์ของนักเรียน ป.6', 'ศึกษาผลการใช้-scratch-ความคิดสร้างสรรค์', 'ศึกษาผลของการจัดการเรียนรู้ด้วยโปรแกรม Scratch ที่มีต่อความคิดสร้างสรรค์ 4 องค์ประกอบ', '<h3>วัตถุประสงค์</h3><p>เพื่อเปรียบเทียบความคิดสร้างสรรค์ก่อนและหลังการจัดการเรียนรู้ด้วย Scratch และศึกษาความพึงพอใจของผู้เรียน</p><h3>วิธีดำเนินการ</h3><p>กลุ่มตัวอย่าง 28 คน จัดการเรียนรู้ 12 คาบ วัดความคิดสร้างสรรค์ด้วยแบบวัดของ Torrance ฉบับภาษาไทย ประเมิน 4 องค์ประกอบ ได้แก่ ความคล่องแคล่ว ความยืดหยุ่น ความริเริ่ม และความละเอียดลออ</p><h3>ผลการศึกษา</h3><p>ความคิดสร้างสรรค์หลังเรียนสูงกว่าก่อนเรียนอย่างมีนัยสำคัญทางสถิติที่ระดับ .01 องค์ประกอบที่เพิ่มขึ้นสูงสุดคือความริเริ่ม ความพึงพอใจอยู่ในระดับมากที่สุด (4.71)</p>', 2569, 1, '2026-06-18', 'static', 'media/seed/w12_1.jpg', '', 'Scratch,ความคิดสร้างสรรค์,วิจัย,ป.6', 142, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (13, 7, 'มุมนักสร้างสรรค์ “Maker Corner” ในห้องคอมพิวเตอร์', 'maker-corner-ห้องคอมพิวเตอร์', 'จัดสภาพแวดล้อมการเรียนรู้แบบ Maker Space ให้นักเรียนได้ลงมือประดิษฐ์ ทดลอง และแสดงผลงาน', '<h3>แนวคิด</h3><p>ห้องเรียนควรเป็นพื้นที่ที่นักเรียนกล้าลองผิดลองถูก จึงจัด Maker Corner ให้เป็นพื้นที่เปิดสำหรับสร้างสรรค์ผลงานนอกเวลาเรียน</p><h3>การจัดสภาพแวดล้อม</h3><p>จัดโซนอุปกรณ์ (บอร์ดสมองกลฝังตัว เซนเซอร์ วัสดุรีไซเคิล) โซนทำงานกลุ่ม โซนแสดงผลงานนักเรียน และผนังไอเดียที่ให้นักเรียนติดโพสต์อิทเสนอโครงงาน พร้อมข้อตกลงการใช้ห้องที่นักเรียนร่วมกันกำหนด</p><h3>ผลที่เกิดขึ้น</h3><p>มีนักเรียนใช้บริการนอกเวลาเรียนเฉลี่ย 24 คน/สัปดาห์ เกิดโครงงานนักเรียน 7 ชิ้น และผลการประเมินความสุขในการเรียนอยู่ในระดับมากที่สุด</p>', 2568, 2, '2025-12-15', 'static', 'media/seed/w13_1.jpg', '', 'Maker Space,บรรยากาศชั้นเรียน,STEM', 134, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (14, 7, 'ห้องเรียนปลอดภัยไซเบอร์ “Cyber Safe Classroom”', 'ห้องเรียนปลอดภัยไซเบอร์', 'สร้างข้อตกลงการใช้อินเทอร์เน็ตร่วมกัน ติดตั้งระบบกรองเนื้อหา และมุมให้คำปรึกษาออนไลน์', '<h3>ที่มา</h3><p>พบเหตุการณ์นักเรียนถูกกลั่นแกล้งทางออนไลน์ (Cyberbullying) ในกลุ่มแชทของห้องเรียน</p><h3>การดำเนินการ</h3><p>จัดกิจกรรมสร้างข้อตกลงห้องเรียนร่วมกับนักเรียน ติดตั้งระบบกรองเนื้อหาบนเครื่องคอมพิวเตอร์ทุกเครื่อง จัดมุม “กล่องปรึกษาลับ” ทั้งแบบกล่องจริงและ Google Form และอบรมแกนนำนักเรียน 10 คนเป็น Cyber Buddy</p><h3>ผลที่เกิดขึ้น</h3><p>เหตุการณ์กลั่นแกล้งออนไลน์ที่รายงานลดลงจาก 6 เหตุการณ์เหลือ 0 ใน 1 ภาคเรียน นักเรียนร้อยละ 94 รู้สึกปลอดภัยเมื่อใช้อินเทอร์เน็ตในโรงเรียน</p>', 2569, 1, '2026-06-08', 'static', 'media/seed/w14_1.jpg', '', 'Cyberbullying,ความปลอดภัยไซเบอร์,บรรยากาศ', 121, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (15, 8, 'โครงการ “พลเมืองดิจิทัลรุ่นเยาว์” ปลูกฝังจริยธรรมการใช้สื่อ', 'โครงการพลเมืองดิจิทัลรุ่นเยาว์', 'อบรมและพัฒนาคุณลักษณะพลเมืองดิจิทัล 9 องค์ประกอบ ผ่านกิจกรรมบทบาทสมมติและกรณีศึกษา', '<h3>วัตถุประสงค์</h3><p>เพื่อปลูกฝังคุณลักษณะอันพึงประสงค์ด้านความซื่อสัตย์ มีวินัย และรับผิดชอบต่อสังคมในโลกดิจิทัล</p><h3>กิจกรรม</h3><p>จัดอบรม 6 ครั้ง ครั้งละ 2 ชั่วโมง ใช้กรณีศึกษาจากเหตุการณ์จริง กิจกรรมบทบาทสมมติเรื่องการละเมิดลิขสิทธิ์ การให้เครดิตผลงานผู้อื่น และการตรวจสอบข่าวปลอม ปิดท้ายด้วยการที่นักเรียนผลิตคลิปสั้นรณรงค์</p><h3>ผลที่เกิดกับผู้เรียน</h3><p>ผลประเมินคุณลักษณะอันพึงประสงค์อยู่ในระดับดีเยี่ยมร้อยละ 87 นักเรียนผลิตคลิปรณรงค์ 16 เรื่อง เผยแพร่ผ่านเพจโรงเรียนมียอดชมรวมกว่า 12,000 ครั้ง</p>', 2569, 1, '2026-06-30', 'static', 'media/seed/w15_1.jpg', '', 'พลเมืองดิจิทัล,จริยธรรม,คุณลักษณะอันพึงประสงค์', 158, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (16, 8, 'กิจกรรมโฮมรูมสร้างวินัยเชิงบวก “ธนาคารความดี”', 'กิจกรรมโฮมรูม-ธนาคารความดี', 'ใช้ระบบเสริมแรงทางบวกบันทึกความดีรายบุคคล ลดพฤติกรรมไม่พึงประสงค์ในชั้นเรียน', '<h3>สภาพปัญหา</h3><p>นักเรียนมาสายและส่งงานไม่ตรงเวลาบ่อยครั้ง การลงโทษแบบเดิมไม่ได้ผลระยะยาว</p><h3>วิธีดำเนินการ</h3><p>จัดทำสมุดบัญชี “ธนาคารความดี” ให้นักเรียนบันทึกพฤติกรรมดีที่ทำในแต่ละวัน เพื่อนและครูร่วมรับรอง สะสมแต้มแลกสิทธิพิเศษเชิงบวก เช่น เป็นผู้ช่วยครู เลือกเพลงในคาบ จัดพิธียกย่องรายเดือน</p><h3>ผลลัพธ์</h3><p>สถิติการมาสายลดลงร้อยละ 71 การส่งงานตรงเวลาเพิ่มจากร้อยละ 68 เป็น 93 ภายใน 1 ภาคเรียน</p>', 2568, 2, '2026-01-16', 'static', 'media/seed/w16_1.jpg', '', 'วินัยเชิงบวก,โฮมรูม,เสริมแรงทางบวก', 112, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (17, 9, 'ระบบสารสนเทศนักเรียนรายบุคคล ด้วย Google Sheets + Looker Studio', 'ระบบสารสนเทศนักเรียนรายบุคคล', 'จัดทำฐานข้อมูลนักเรียนรายบุคคลและแดชบอร์ดสารสนเทศ ครูดูผลการเรียน การมาเรียน และพฤติกรรมได้ในหน้าเดียว', '<h3>วัตถุประสงค์</h3><p>เพื่อให้ข้อมูลผู้เรียนถูกจัดเก็บอย่างเป็นระบบ เรียกใช้ได้ทันที และนำไปสู่การตัดสินใจเชิงพัฒนา</p><h3>การดำเนินการ</h3><p>ออกแบบโครงสร้างข้อมูล 6 ตาราง (ข้อมูลพื้นฐาน ผลการเรียน การมาเรียน SDQ พฤติกรรม และการเยี่ยมบ้าน) เชื่อมต่อกับ Looker Studio สร้างแดชบอร์ดกรองตามห้องเรียนและรายบุคคล กำหนดสิทธิ์การเข้าถึงเฉพาะครูที่เกี่ยวข้อง</p><h3>ผลที่เกิดขึ้น</h3><p>ลดเวลาจัดทำรายงานจาก 4 ชั่วโมงเหลือ 15 นาที ครูประจำชั้นใช้ข้อมูลวางแผนช่วยเหลือนักเรียนได้ทันเวลา</p>', 2569, 1, '2026-05-22', 'static', 'media/seed/w17_1.jpg', '', 'สารสนเทศ,Looker Studio,ข้อมูลผู้เรียน', 149, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (18, 9, 'จัดทำ ปพ.5 อิเล็กทรอนิกส์ และรายงานผลรายวิชา', 'ปพ5-อิเล็กทรอนิกส์-รายงานผลรายวิชา', 'พัฒนาแบบฟอร์ม ปพ.5 อิเล็กทรอนิกส์ คำนวณคะแนนอัตโนมัติ ลดความผิดพลาดจากการกรอกมือ', '<h3>ที่มา</h3><p>การกรอก ปพ.5 ด้วยมือเกิดข้อผิดพลาดในการคำนวณบ่อย และใช้เวลามากช่วงปลายภาค</p><h3>การพัฒนา</h3><p>ออกแบบสเปรดชีตที่แยกคะแนนเก็บ กลางภาค ปลายภาค คุณลักษณะอันพึงประสงค์ การอ่านคิดวิเคราะห์และเขียน คำนวณเกรดอัตโนมัติตามเกณฑ์สถานศึกษา พร้อมส่งออก PDF</p><h3>ผลลัพธ์</h3><p>ข้อผิดพลาดจากการคำนวณเป็นศูนย์ ครูในกลุ่มสาระ 6 คนนำไปใช้ร่วมกัน และฝ่ายวิชาการขยายผลไปยังกลุ่มสาระอื่น</p>', 2568, 2, '2026-03-20', 'static', 'media/seed/w18_1.jpg', '', 'ปพ.5,สารสนเทศรายวิชา,สเปรดชีต', 96, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (19, 10, 'เยี่ยมบ้านนักเรียนครบ 100% พร้อมคัดกรอง SDQ ภาคเรียนที่ 1', 'เยี่ยมบ้านนักเรียนครบ-100-คัดกรอง-sdq', 'ดำเนินการตามระบบดูแลช่วยเหลือนักเรียนครบ 5 ขั้นตอน เยี่ยมบ้านนักเรียนทุกคนในความรับผิดชอบ', '<h3>การดำเนินการตามระบบ 5 ขั้นตอน</h3><p>ขั้นที่ 1 รู้จักนักเรียนเป็นรายบุคคล โดยเยี่ยมบ้านนักเรียน 32 คน ครบร้อยละ 100 ขั้นที่ 2 คัดกรองด้วยแบบประเมิน SDQ ทั้งฉบับนักเรียน ครู และผู้ปกครอง ขั้นที่ 3 ส่งเสริมนักเรียนกลุ่มปกติด้วยกิจกรรมโฮมรูมและแนะแนว ขั้นที่ 4 ป้องกันและแก้ไขนักเรียนกลุ่มเสี่ยง 5 คน ด้วยการให้คำปรึกษารายบุคคลและประสานผู้ปกครอง ขั้นที่ 5 ส่งต่อภายในไปยังครูแนะแนว 1 ราย</p><h3>ผลลัพธ์</h3><p>นักเรียนกลุ่มเสี่ยงด้านพฤติกรรมลดจาก 5 คนเหลือ 1 คน อัตราการมาเรียนเพิ่มเป็นร้อยละ 98.4 ผู้ปกครองพึงพอใจต่อการดูแลของครูในระดับมากที่สุด</p>', 2569, 1, '2026-06-20', 'static', 'media/seed/w19_1.jpg', '', 'ระบบดูแลช่วยเหลือ,SDQ,เยี่ยมบ้าน', 187, 1, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (20, 10, 'ระบบติดตามนักเรียนกลุ่มเสี่ยง ด้วยแดชบอร์ดแจ้งเตือนอัตโนมัติ', 'ระบบติดตามนักเรียนกลุ่มเสี่ยง', 'สร้างระบบแจ้งเตือนอัตโนมัติเมื่อนักเรียนขาดเรียนติดต่อกันหรือคะแนนตกเกณฑ์ ส่งไลน์แจ้งครูประจำชั้นทันที', '<h3>แนวคิด</h3><p>การช่วยเหลือที่ทันเวลาสำคัญกว่าการรายงานย้อนหลัง จึงออกแบบระบบแจ้งเตือนเชิงรุก</p><h3>การพัฒนา</h3><p>เชื่อมข้อมูลการมาเรียนและคะแนนเก็บเข้ากับ Google Apps Script ตั้งเงื่อนไขแจ้งเตือนเมื่อขาดเรียนติดต่อกัน 3 วัน หรือคะแนนเก็บต่ำกว่าร้อยละ 50 ส่งข้อความอัตโนมัติเข้ากลุ่มไลน์ครูประจำชั้น</p><h3>ผลที่เกิดขึ้น</h3><p>ระยะเวลาเฉลี่ยในการเข้าช่วยเหลือนักเรียนลดจาก 9 วันเหลือ 2 วัน ไม่มีนักเรียนออกกลางคันในปีการศึกษานี้</p>', 2569, 1, '2026-06-26', 'static', 'media/seed/w20_1.jpg', '', 'แจ้งเตือน,กลุ่มเสี่ยง,Apps Script', 131, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (21, 11, 'หัวหน้างานโสตทัศนศึกษา จัดระบบห้องสื่อและอุปกรณ์', 'หัวหน้างานโสตทัศนศึกษา-จัดระบบห้องสื่อ', 'ปฏิบัติหน้าที่หัวหน้างานโสตทัศนศึกษา จัดทำระบบยืม-คืนอุปกรณ์ออนไลน์ และคู่มือการใช้ห้องสื่อ', '<h3>ขอบเขตงาน</h3><p>ดูแลอุปกรณ์โสตทัศนูปกรณ์ทั้งหมดของโรงเรียน 148 รายการ รวมถึงห้องประชุมและระบบเสียงในกิจกรรมสำคัญ</p><h3>การดำเนินการ</h3><p>จัดทำทะเบียนครุภัณฑ์พร้อม QR Code รายชิ้น พัฒนาระบบจองและยืม-คืนออนไลน์ จัดทำคู่มือการใช้งานพร้อมวิดีโอสาธิต และกำหนดรอบบำรุงรักษาเชิงป้องกันทุกภาคเรียน</p><h3>ผลลัพธ์</h3><p>อุปกรณ์สูญหายเป็นศูนย์ ระยะเวลาเตรียมงานกิจกรรมลดลงร้อยละ 40 ได้รับการประเมินการปฏิบัติงานระดับดีเยี่ยม</p>', 2569, 1, '2026-05-28', 'static', 'media/seed/w21_1.jpg', '', 'งานโสตฯ,ครุภัณฑ์,QR Code,งานสนับสนุน', 104, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (22, 11, 'พัฒนาเว็บไซต์โรงเรียนและระบบประชาสัมพันธ์ออนไลน์', 'พัฒนาเว็บไซต์โรงเรียน-ระบบประชาสัมพันธ์', 'ออกแบบและพัฒนาเว็บไซต์โรงเรียนใหม่ รองรับมือถือ พร้อมระบบข่าวสารที่ครูอัปเดตเองได้', '<h3>ปัญหาเดิม</h3><p>เว็บไซต์โรงเรียนเดิมไม่รองรับมือถือ ข้อมูลไม่เป็นปัจจุบัน และครูอัปเดตข่าวเองไม่ได้</p><h3>การดำเนินการ</h3><p>วิเคราะห์ความต้องการของผู้ใช้ ออกแบบใหม่แบบ Mobile-first พัฒนาระบบจัดการเนื้อหาให้ครูเพิ่มข่าวได้เอง จัดอบรมการใช้งานแก่ครู 12 คน และเชื่อมต่อกับเพจเฟซบุ๊กโรงเรียน</p><h3>ผลลัพธ์</h3><p>ยอดผู้เข้าชมเว็บไซต์เพิ่มขึ้นร้อยละ 340 ข่าวสารได้รับการอัปเดตเฉลี่ย 8 เรื่อง/เดือน โดยครูผู้รับผิดชอบเอง</p>', 2568, 2, '2026-02-19', 'static', 'media/seed/w22_1.jpg', '', 'เว็บไซต์โรงเรียน,ประชาสัมพันธ์,งานสนับสนุน', 118, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (23, 12, 'เปิดบ้านวิชาการ Open House ร่วมกับผู้ปกครองและชุมชน', 'เปิดบ้านวิชาการ-open-house', 'จัดงานเปิดบ้านวิชาการ มีผู้ปกครองและชุมชนเข้าร่วมกว่า 380 คน นักเรียนนำเสนอผลงานด้วยตนเอง', '<h3>วัตถุประสงค์</h3><p>เพื่อเปิดโอกาสให้ผู้ปกครองและชุมชนเห็นพัฒนาการของผู้เรียน และร่วมเป็นส่วนหนึ่งในการพัฒนาคุณภาพการศึกษา</p><h3>การดำเนินการ</h3><p>รับผิดชอบซุ้มนิทรรศการกลุ่มสาระวิทยาศาสตร์และเทคโนโลยี ให้นักเรียนเป็นผู้นำเสนอผลงาน AR หุ่นยนต์ และเว็บแอปที่พัฒนาขึ้นเอง จัดเวิร์กช็อป “ผู้ปกครองรู้ทันโลกดิจิทัล” 2 รอบ และเก็บแบบสอบถามความคิดเห็น</p><h3>ผลลัพธ์</h3><p>ผู้เข้าร่วม 380 คน ความพึงพอใจเฉลี่ย 4.68 จาก 5 เกิดอาสาสมัครผู้ปกครองช่วยดูแลกิจกรรมชุมนุมคอมพิวเตอร์ 6 คน</p>', 2569, 1, '2026-07-04', 'static', 'media/seed/w23_1.jpg', '', 'Open House,ผู้ปกครอง,ชุมชน,ภาคีเครือข่าย', 143, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (24, 12, 'บันทึกข้อตกลง (MOU) เครือข่ายโรงเรียน Coding ร่วมกับวิทยาลัยเทคนิค', 'mou-เครือข่ายโรงเรียน-coding', 'ประสานความร่วมมือกับวิทยาลัยเทคนิคและโรงเรียนเครือข่าย 5 แห่ง จัดค่ายและแลกเปลี่ยนวิทยากร', '<h3>ที่มา</h3><p>โรงเรียนขาดแคลนอุปกรณ์และวิทยากรเฉพาะทางด้านหุ่นยนต์ จึงแสวงหาความร่วมมือจากภายนอก</p><h3>การดำเนินการ</h3><p>ประสานงานและร่างบันทึกข้อตกลงความร่วมมือกับวิทยาลัยเทคนิคในพื้นที่ และโรงเรียนเครือข่าย 5 แห่ง ครอบคลุมการใช้ห้องปฏิบัติการร่วมกัน การแลกเปลี่ยนวิทยากร และการจัดค่ายร่วม 2 ครั้ง/ปี</p><h3>ผลลัพธ์</h3><p>นักเรียน 120 คนได้ใช้ห้องปฏิบัติการหุ่นยนต์มาตรฐาน ครูได้รับการนิเทศจากอาจารย์ผู้เชี่ยวชาญ 4 ครั้ง และเกิดทีมแข่งขันระดับภาค 1 ทีม</p>', 2569, 1, '2026-06-15', 'static', 'media/seed/w24_1.jpg', '', 'MOU,ภาคีเครือข่าย,ความร่วมมือ', 108, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (25, 13, 'อบรมเชิงปฏิบัติการ “AI เพื่อการจัดการเรียนรู้” 16 ชั่วโมง', 'อบรม-ai-เพื่อการจัดการเรียนรู้', 'พัฒนาตนเองตามแผน ID Plan เข้าอบรมเชิงปฏิบัติการด้านปัญญาประดิษฐ์ จัดโดย สพฐ. 16 ชั่วโมง', '<h3>ความสอดคล้องกับแผนพัฒนาตนเอง</h3><p>ตามแผนพัฒนาตนเองรายบุคคล (ID Plan) ปีงบประมาณ 2569 ได้กำหนดเป้าหมายพัฒนาสมรรถนะด้านการใช้เทคโนโลยีปัญญาประดิษฐ์ในการจัดการเรียนรู้</p><h3>เนื้อหาการอบรม</h3><p>หลักการทำงานของ Generative AI, การออกแบบ Prompt เพื่อสร้างสื่อและแผนการสอน, การใช้ AI ช่วยวิเคราะห์ผลการเรียนรู้, จริยธรรมและข้อควรระวังในการใช้ AI กับผู้เรียน</p><h3>การนำมาใช้</h3><p>นำความรู้มาพัฒนาใบงานเฉพาะบุคคล (Differentiated Worksheet) และเครื่องมือประเมินอัตโนมัติ ใช้จริงกับนักเรียน 3 ห้องเรียน</p>', 2569, 1, '2026-05-15', 'static', 'media/seed/w25_1.jpg', '', 'อบรม,AI,พัฒนาตนเอง,ID Plan', 312, 1, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (26, 13, 'หลักสูตรออนไลน์ Google Certified Educator Level 2', 'google-certified-educator-level-2', 'ศึกษาหลักสูตรออนไลน์ด้วยตนเองและสอบผ่านการรับรอง Google Certified Educator ระดับ 2', '<h3>เหตุผลในการพัฒนา</h3><p>โรงเรียนใช้ Google Workspace for Education เป็นเครื่องมือหลัก การมีความเชี่ยวชาญระดับสูงจะช่วยยกระดับการจัดการเรียนรู้และช่วยเหลือเพื่อนครู</p><h3>กระบวนการ</h3><p>ศึกษาด้วยตนเองผ่าน Teacher Center รวม 22 ชั่วโมง ครอบคลุมการใช้ Classroom ขั้นสูง การวิเคราะห์ข้อมูลผู้เรียน การสร้างสื่อมัลติมีเดีย และการสอบภาคปฏิบัติ 3 ชั่วโมง</p><h3>ผลลัพธ์</h3><p>สอบผ่านการรับรองระดับ 2 และได้รับมอบหมายเป็นครูพี่เลี้ยงอบรมภายในให้เพื่อนครู 12 คน</p>', 2568, 2, '2026-03-14', 'static', 'media/seed/w26_1.jpg', '', 'Google Certified,พัฒนาตนเอง,ออนไลน์', 127, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (27, 14, 'ชุมชนการเรียนรู้ทางวิชาชีพ (PLC) กลุ่มสาระวิทยาศาสตร์ฯ วงรอบที่ 1–4', 'plc-กลุ่มสาระวิทยาศาสตร์-วงรอบ-1-4', 'ร่วมกิจกรรม PLC 4 วงรอบ ตลอดปีการศึกษา รวม 20 ชั่วโมง ในประเด็นการพัฒนาการคิดเชิงคำนวณ', '<h3>ประเด็นปัญหาที่ร่วมกันแก้</h3><p>สมาชิก PLC 6 คน ร่วมกันวิเคราะห์ว่านักเรียนขาดทักษะการลำดับขั้นตอนการแก้ปัญหา ซึ่งส่งผลต่อทั้งวิชาวิทยาศาสตร์และคณิตศาสตร์</p><h3>กระบวนการ PLC</h3><p>วงรอบที่ 1 วิเคราะห์ปัญหาและกำหนดเป้าหมายร่วม วงรอบที่ 2 ออกแบบแผนและนวัตกรรมร่วมกัน (บอร์ดเกมและกิจกรรม Unplugged) วงรอบที่ 3 เปิดชั้นเรียน (Open Class) สังเกตการสอนและสะท้อนผล วงรอบที่ 4 ปรับปรุงและถอดบทเรียน จัดทำรายงานเผยแพร่</p><h3>ผลที่เกิดขึ้น</h3><p>เกิดนวัตกรรมร่วม 2 ชิ้น ครูในกลุ่มนำไปใช้ครบทุกคน นักเรียนที่มีปัญหาการลำดับขั้นตอนลดลงร้อยละ 33 และผลงาน PLC ได้รับคัดเลือกนำเสนอระดับเขตพื้นที่</p>', 2569, 1, '2026-06-10', 'static', 'media/seed/w27_1.jpg', '', 'PLC,ชุมชนการเรียนรู้,Open Class', 165, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (28, 14, 'วิทยากรแลกเปลี่ยนเรียนรู้ เวที Symposium ระดับเขตพื้นที่', 'วิทยากร-symposium-ระดับเขตพื้นที่', 'ได้รับเชิญเป็นวิทยากรแลกเปลี่ยนเรียนรู้ นำเสนอนวัตกรรมสื่อ AR ต่อครูในเขตพื้นที่ 120 คน', '<h3>บทบาท</h3><p>วิทยากรนำเสนอผลงาน “สื่อ AR ระบบสุริยะ” และกระบวนการพัฒนานวัตกรรมจากปัญหาในชั้นเรียนจริง</p><h3>เนื้อหาการนำเสนอ</h3><p>การวิเคราะห์ปัญหาผู้เรียน การเลือกเทคโนโลยีที่เหมาะสมกับบริบทและงบประมาณ ขั้นตอนการพัฒนาสื่อโดยไม่ต้องเขียนโปรแกรม การประเมินประสิทธิผล และการต่อยอด</p><h3>ผลที่เกิดขึ้น</h3><p>ครูผู้เข้าร่วม 120 คน ประเมินความพึงพอใจเฉลี่ย 4.74 มีโรงเรียน 8 แห่งขอนำสื่อไปใช้ต่อ และเกิดเครือข่ายครูนวัตกรรม 1 เครือข่าย</p>', 2569, 1, '2026-07-02', 'static', 'media/seed/w28_1.jpg', '', 'วิทยากร,Symposium,แลกเปลี่ยนเรียนรู้', 89, 0, 'published', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (29, 15, 'นำเทคนิค AI Prompt มาออกแบบใบงานเฉพาะบุคคล (Differentiated Worksheet)', 'นำ-ai-prompt-ออกแบบใบงานเฉพาะบุคคล', 'นำความรู้จากการอบรม AI มาสร้างใบงาน 3 ระดับความยาก ตอบสนองความแตกต่างระหว่างบุคคล', '<h3>ความเชื่อมโยงกับการพัฒนาตนเอง</h3><p>ต่อยอดจากการอบรม “AI เพื่อการจัดการเรียนรู้” 16 ชั่วโมง มาสู่การใช้งานจริงในชั้นเรียน</p><h3>การนำมาใช้</h3><p>ออกแบบชุด Prompt สำหรับสร้างใบงาน 3 ระดับ (พื้นฐาน ปานกลาง ท้าทาย) จากตัวชี้วัดเดียวกัน ตรวจสอบความถูกต้องทางวิชาการโดยครูก่อนนำไปใช้ทุกครั้ง และจัดกลุ่มนักเรียนตามผลการวินิจฉัยก่อนเรียน</p><h3>ผลที่เกิดกับผู้เรียน</h3><p>นักเรียนกลุ่มอ่อนมีคะแนนเพิ่มขึ้นเฉลี่ยร้อยละ 22 กลุ่มเก่งได้รับความท้าทายเพิ่มขึ้น และเวลาที่ครูใช้เตรียมใบงานลดลงร้อยละ 55</p>', 2569, 1, '2026-07-06', 'static', 'media/seed/w29_1.jpg', '', 'AI,Differentiated Instruction,ใบงาน', 0, 0, 'draft', '2026-09-06 15:28:07', NULL);
INSERT INTO works (id, indicator_id, title, slug, summary, content, academic_year, semester, work_date, cover_source, cover_ref, video_url, tags, view_count, is_featured, status, created_at, deleted_at) VALUES (30, 15, 'ถอดบทเรียน PLC สู่การปรับแผนการสอนจริงในชั้นเรียน', 'ถอดบทเรียน-plc-ปรับแผนการสอน', 'นำผลสะท้อนจากวง PLC มาปรับแผนการจัดการเรียนรู้ 6 แผน และติดตามผลกับนักเรียนจริง', '<h3>ที่มา</h3><p>ผลการเปิดชั้นเรียนในวง PLC ชี้ว่าขั้นนำของแผนใช้เวลานานเกินไป และคำถามกระตุ้นยังไม่ท้าทายพอ</p><h3>การปรับปรุง</h3><p>ปรับแผน 6 แผน ลดเวลาขั้นนำจาก 15 เหลือ 8 นาที เพิ่มคำถามระดับวิเคราะห์และประเมินค่า ปรับใบงานให้มีสถานการณ์ปลายเปิด และเพิ่มขั้นสะท้อนคิด (Reflection) ท้ายคาบ</p><h3>ผลที่เกิดขึ้น</h3><p>เวลาปฏิบัติกิจกรรมของนักเรียนเพิ่มขึ้น 7 นาที/คาบ คะแนนคำถามระดับวิเคราะห์เพิ่มขึ้นร้อยละ 19 และครูในวง PLC นำแนวทางไปใช้ต่อ 4 คน</p>', 2569, 1, '2026-07-07', 'static', 'media/seed/w30_1.jpg', '', 'PLC,ถอดบทเรียน,ปรับแผนการสอน', 0, 0, 'draft', '2026-09-06 15:28:07', NULL);
