INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (1, 1, 1, 'ปรับปรุงและพัฒนาหน่วยการเรียนรู้รายวิชาวิทยาการคำนวณ ให้สอดคล้องกับหลักสูตรสถานศึกษาและบริบทผู้เรียน', 'หน่วยการเรียนรู้ 2 หน่วย และรายวิชาเพิ่มเติม 1 รายวิชา', 'ผ่านการพิจารณาเห็นชอบจากคณะกรรมการบริหารหลักสูตรสถานศึกษา', 1);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (2, 1, 2, 'จัดทำแผนการจัดการเรียนรู้เชิงรุก (Active Learning) ที่เน้นผู้เรียนเป็นสำคัญ', 'แผนการจัดการเรียนรู้ 20 แผน/ปีการศึกษา', 'นักเรียนบรรลุจุดประสงค์การเรียนรู้ไม่น้อยกว่าร้อยละ 80', 2);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (3, 1, 3, 'จัดกิจกรรมการเรียนรู้ที่ให้ผู้เรียนได้ลงมือปฏิบัติจริงและสร้างองค์ความรู้ด้วยตนเอง', 'กิจกรรมหลัก 4 กิจกรรม/ภาคเรียน', 'ผู้เรียนมีส่วนร่วมในกิจกรรมไม่น้อยกว่าร้อยละ 90 และมีความพึงพอใจระดับมากขึ้นไป', 3);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (4, 1, 4, 'พัฒนาสื่อ AR เกมการศึกษา และเว็บแอปพลิเคชันประกอบการเรียนวิทยาการคำนวณ', 'สื่อ/นวัตกรรม 4 ชิ้น/ปี', 'ความพึงพอใจของผู้เรียนต่อสื่อไม่น้อยกว่า 4.50 จาก 5.00', 4);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (5, 1, 5, 'พัฒนาเครื่องมือวัดและประเมินผลตามสภาพจริง พร้อมเกณฑ์การให้คะแนนแบบรูบริก', 'เครื่องมือวัด 3 ชุด และคลังข้อสอบ 300 ข้อ', 'เครื่องมือผ่านการตรวจค่า IOC จากผู้เชี่ยวชาญไม่ต่ำกว่า 0.60 ทุกข้อ', 5);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (6, 1, 6, 'ทำวิจัยในชั้นเรียนเพื่อแก้ปัญหาการลำดับขั้นตอนการแก้ปัญหาของผู้เรียน', 'งานวิจัยในชั้นเรียน 1 เรื่อง/ปีการศึกษา', 'ผลสัมฤทธิ์หลังการใช้นวัตกรรมสูงกว่าก่อนใช้อย่างมีนัยสำคัญทางสถิติที่ระดับ .05', 6);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (7, 1, 7, 'จัดบรรยากาศห้องเรียนและห้องปฏิบัติการคอมพิวเตอร์ให้ปลอดภัย เอื้อต่อการเรียนรู้', 'ปรับปรุงพื้นที่เรียนรู้ 2 จุด (Maker Corner และมุมปรึกษา)', 'ผู้เรียนประเมินความสุขและความปลอดภัยในการเรียนระดับมากที่สุด', 7);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (8, 1, 8, 'อบรมและปลูกฝังคุณลักษณะพลเมืองดิจิทัลและคุณลักษณะอันพึงประสงค์แก่ผู้เรียน', 'กิจกรรมอบรม 6 ครั้ง/ปี', 'ผู้เรียนผ่านการประเมินคุณลักษณะอันพึงประสงค์ระดับดีขึ้นไปไม่น้อยกว่าร้อยละ 85', 8);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (9, 1, 9, 'จัดทำและปรับปรุงข้อมูลสารสนเทศของผู้เรียนรายบุคคลและสารสนเทศรายวิชา', 'ฐานข้อมูลนักเรียน 1 ระบบ และ ปพ.5 อิเล็กทรอนิกส์ครบทุกรายวิชาที่สอน', 'ข้อมูลถูกต้อง เป็นปัจจุบัน และเรียกใช้ได้ภายใน 5 นาที', 1);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (10, 1, 10, 'ดำเนินการตามระบบดูแลช่วยเหลือนักเรียนครบ 5 ขั้นตอน รวมถึงการเยี่ยมบ้านและคัดกรอง SDQ', 'เยี่ยมบ้านนักเรียนในความรับผิดชอบครบร้อยละ 100 (32 คน)', 'มีข้อมูลคัดกรองรายบุคคลครบถ้วน และนักเรียนกลุ่มเสี่ยงได้รับการช่วยเหลือทุกราย', 2);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (11, 1, 11, 'ปฏิบัติหน้าที่หัวหน้างานโสตทัศนศึกษา และงานประชาสัมพันธ์ของสถานศึกษา', 'ปฏิบัติงานตามที่ได้รับมอบหมายครบ 100% และสนับสนุนกิจกรรมโรงเรียนไม่น้อยกว่า 12 ครั้ง/ปี', 'ผลการประเมินการปฏิบัติงานอยู่ในระดับดีเยี่ยม ไม่มีข้อร้องเรียน', 3);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (12, 1, 12, 'ประสานความร่วมมือกับผู้ปกครอง ชุมชน และภาคีเครือข่ายเพื่อร่วมพัฒนาผู้เรียน', 'กิจกรรมร่วมกับเครือข่าย 3 กิจกรรม และบันทึกข้อตกลง (MOU) 1 ฉบับ', 'ผู้ปกครองและภาคีเครือข่ายมีความพึงพอใจไม่น้อยกว่า 4.50 จาก 5.00', 4);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (13, 1, 13, 'พัฒนาตนเองตามแผนพัฒนาตนเองรายบุคคล (ID Plan) อย่างต่อเนื่อง', 'เข้ารับการพัฒนาไม่น้อยกว่า 20 ชั่วโมง/ปีงบประมาณ', 'มีเกียรติบัตรรับรอง และสามารถนำความรู้ไปใช้ในการจัดการเรียนรู้ได้จริง', 1);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (14, 1, 14, 'เข้าร่วมชุมชนการเรียนรู้ทางวิชาชีพ (PLC) ของกลุ่มสาระการเรียนรู้อย่างสม่ำเสมอ', 'เข้าร่วม PLC ไม่น้อยกว่า 4 วงรอบ รวม 20 ชั่วโมง/ปี', 'เกิดนวัตกรรมร่วมอย่างน้อย 1 ชิ้น และมีบันทึกการสะท้อนผลครบทุกวงรอบ', 2);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (15, 1, 15, 'นำความรู้และทักษะที่ได้จากการพัฒนาตนเองและ PLC มาปรับใช้ในการจัดการเรียนรู้', 'ปรับปรุงแผนการจัดการเรียนรู้อย่างน้อย 6 แผน และสร้างนวัตกรรมต่อยอด 1 ชิ้น', 'ผลสัมฤทธิ์ทางการเรียนของผู้เรียนสูงขึ้นไม่น้อยกว่าร้อยละ 15', 3);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (16, 2, 1, 'ปรับปรุงและพัฒนาหน่วยการเรียนรู้รายวิชาวิทยาการคำนวณ ให้สอดคล้องกับหลักสูตรสถานศึกษาและบริบทผู้เรียน', 'หน่วยการเรียนรู้ 2 หน่วย และรายวิชาเพิ่มเติม 1 รายวิชา', 'ผ่านการพิจารณาเห็นชอบจากคณะกรรมการบริหารหลักสูตรสถานศึกษา', 1);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (17, 2, 2, 'จัดทำแผนการจัดการเรียนรู้เชิงรุก (Active Learning) ที่เน้นผู้เรียนเป็นสำคัญ', 'แผนการจัดการเรียนรู้ 20 แผน/ปีการศึกษา', 'นักเรียนบรรลุจุดประสงค์การเรียนรู้ไม่น้อยกว่าร้อยละ 80', 2);
