INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (34, 3, 4, 'พัฒนาสื่อ AR เกมการศึกษา และเว็บแอปพลิเคชันประกอบการเรียนวิทยาการคำนวณ', 'สื่อ/นวัตกรรม 4 ชิ้น/ปี', 'ความพึงพอใจของผู้เรียนต่อสื่อไม่น้อยกว่า 4.50 จาก 5.00', 4);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (35, 3, 5, 'พัฒนาเครื่องมือวัดและประเมินผลตามสภาพจริง พร้อมเกณฑ์การให้คะแนนแบบรูบริก', 'เครื่องมือวัด 3 ชุด และคลังข้อสอบ 300 ข้อ', 'เครื่องมือผ่านการตรวจค่า IOC จากผู้เชี่ยวชาญไม่ต่ำกว่า 0.60 ทุกข้อ', 5);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (36, 3, 6, 'ทำวิจัยในชั้นเรียนเพื่อแก้ปัญหาการลำดับขั้นตอนการแก้ปัญหาของผู้เรียน', 'งานวิจัยในชั้นเรียน 1 เรื่อง/ปีการศึกษา', 'ผลสัมฤทธิ์หลังการใช้นวัตกรรมสูงกว่าก่อนใช้อย่างมีนัยสำคัญทางสถิติที่ระดับ .05', 6);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (37, 3, 7, 'จัดบรรยากาศห้องเรียนและห้องปฏิบัติการคอมพิวเตอร์ให้ปลอดภัย เอื้อต่อการเรียนรู้', 'ปรับปรุงพื้นที่เรียนรู้ 2 จุด (Maker Corner และมุมปรึกษา)', 'ผู้เรียนประเมินความสุขและความปลอดภัยในการเรียนระดับมากที่สุด', 7);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (38, 3, 8, 'อบรมและปลูกฝังคุณลักษณะพลเมืองดิจิทัลและคุณลักษณะอันพึงประสงค์แก่ผู้เรียน', 'กิจกรรมอบรม 6 ครั้ง/ปี', 'ผู้เรียนผ่านการประเมินคุณลักษณะอันพึงประสงค์ระดับดีขึ้นไปไม่น้อยกว่าร้อยละ 85', 8);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (39, 3, 9, 'จัดทำและปรับปรุงข้อมูลสารสนเทศของผู้เรียนรายบุคคลและสารสนเทศรายวิชา', 'ฐานข้อมูลนักเรียน 1 ระบบ และ ปพ.5 อิเล็กทรอนิกส์ครบทุกรายวิชาที่สอน', 'ข้อมูลถูกต้อง เป็นปัจจุบัน และเรียกใช้ได้ภายใน 5 นาที', 1);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (40, 3, 10, 'ดำเนินการตามระบบดูแลช่วยเหลือนักเรียนครบ 5 ขั้นตอน รวมถึงการเยี่ยมบ้านและคัดกรอง SDQ', 'เยี่ยมบ้านนักเรียนในความรับผิดชอบครบร้อยละ 100 (32 คน)', 'มีข้อมูลคัดกรองรายบุคคลครบถ้วน และนักเรียนกลุ่มเสี่ยงได้รับการช่วยเหลือทุกราย', 2);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (41, 3, 11, 'ปฏิบัติหน้าที่หัวหน้างานโสตทัศนศึกษา และงานประชาสัมพันธ์ของสถานศึกษา', 'ปฏิบัติงานตามที่ได้รับมอบหมายครบ 100% และสนับสนุนกิจกรรมโรงเรียนไม่น้อยกว่า 12 ครั้ง/ปี', 'ผลการประเมินการปฏิบัติงานอยู่ในระดับดีเยี่ยม ไม่มีข้อร้องเรียน', 3);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (42, 3, 12, 'ประสานความร่วมมือกับผู้ปกครอง ชุมชน และภาคีเครือข่ายเพื่อร่วมพัฒนาผู้เรียน', 'กิจกรรมร่วมกับเครือข่าย 3 กิจกรรม และบันทึกข้อตกลง (MOU) 1 ฉบับ', 'ผู้ปกครองและภาคีเครือข่ายมีความพึงพอใจไม่น้อยกว่า 4.50 จาก 5.00', 4);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (43, 3, 13, 'พัฒนาตนเองตามแผนพัฒนาตนเองรายบุคคล (ID Plan) อย่างต่อเนื่อง', 'เข้ารับการพัฒนาไม่น้อยกว่า 20 ชั่วโมง/ปีงบประมาณ', 'มีเกียรติบัตรรับรอง และสามารถนำความรู้ไปใช้ในการจัดการเรียนรู้ได้จริง', 1);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (44, 3, 14, 'เข้าร่วมชุมชนการเรียนรู้ทางวิชาชีพ (PLC) ของกลุ่มสาระการเรียนรู้อย่างสม่ำเสมอ', 'เข้าร่วม PLC ไม่น้อยกว่า 4 วงรอบ รวม 20 ชั่วโมง/ปี', 'เกิดนวัตกรรมร่วมอย่างน้อย 1 ชิ้น และมีบันทึกการสะท้อนผลครบทุกวงรอบ', 2);
INSERT INTO pa_details (id, agreement_id, indicator_id, task_description, expected_quantity, expected_quality, sort_order) VALUES (45, 3, 15, 'นำความรู้และทักษะที่ได้จากการพัฒนาตนเองและ PLC มาปรับใช้ในการจัดการเรียนรู้', 'ปรับปรุงแผนการจัดการเรียนรู้อย่างน้อย 6 แผน และสร้างนวัตกรรมต่อยอด 1 ชิ้น', 'ผลสัมฤทธิ์ทางการเรียนของผู้เรียนสูงขึ้นไม่น้อยกว่าร้อยละ 15', 3);
INSERT INTO pa_challenges (id, agreement_id, topic, problem_statement, method, expected_outcome) VALUES (1, 1, 'พัฒนาสมรรถนะการคิดเชิงคำนวณของนักเรียน ป.5 ด้วยกิจกรรม Unplugged Coding', 'จากการวิเคราะห์ผลการเรียนรู้และการสังเกตพฤติกรรมในชั้นเรียน พบว่านักเรียนร้อยละ 42 ยังไม่สามารถลำดับขั้นตอนการแก้ปัญหาอย่างเป็นระบบได้ ส่งผลให้เขียนผังงานและโปรแกรมอย่างง่ายไม่สำเร็จ อีกทั้งนักเรียนบางส่วนไม่มีคอมพิวเตอร์ใช้ที่บ้าน ทำให้ขาดโอกาสฝึกฝนอย่างต่อเนื่อง', 'ออกแบบชุดกิจกรรม Unplugged Coding 8 สัปดาห์ ที่ใช้บัตรคำสั่ง บอร์ดเกม และการเคลื่อนไหวร่างกายแทนการใช้คอมพิวเตอร์ ดำเนินการสอนควบคู่กับการประเมินพัฒนาการระหว่างเรียนทุกสัปดาห์ ใช้กระบวนการ PLC ร่วมสะท้อนผลกับเพื่อนครู และปรับกิจกรรมทุก 2 สัปดาห์ตามข้อมูลที่ได้', 'คะแนนเฉลี่ยแบบวัดสมรรถนะการคิดเชิงคำนวณของนักเรียนกลุ่มเป้าหมายเพิ่มขึ้นไม่น้อยกว่าร้อยละ 25 จำนวนนักเรียนที่ลำดับขั้นตอนการแก้ปัญหาไม่ได้ลดลงเหลือไม่เกินร้อยละ 10 และนักเรียนมีเจตคติที่ดีต่อวิชาวิทยาการคำนวณในระดับมากขึ้นไป');
INSERT INTO pa_challenges (id, agreement_id, topic, problem_statement, method, expected_outcome) VALUES (2, 2, 'ยกระดับทักษะการรู้เท่าทันสื่อดิจิทัลของผู้เรียนด้วยกรณีศึกษาข่าวปลอม', 'นักเรียนร้อยละ 56 ไม่สามารถแยกแยะข่าวจริงกับข่าวปลอมได้ และมีการแชร์ข้อมูลที่ไม่ได้ตรวจสอบในกลุ่มออนไลน์ของห้องเรียน', 'จัดการเรียนรู้โดยใช้กรณีศึกษาข่าวปลอมจริง 12 กรณี ร่วมกับเทคนิคการตรวจสอบแหล่งที่มา 5 ขั้นตอน และให้ผู้เรียนผลิตคลิปรณรงค์', 'คะแนนแบบทดสอบการรู้เท่าทันสื่อเพิ่มขึ้นไม่น้อยกว่าร้อยละ 30 และไม่พบการแชร์ข้อมูลเท็จในกลุ่มห้องเรียนตลอดภาคเรียน');
INSERT INTO pa_challenges (id, agreement_id, topic, problem_statement, method, expected_outcome) VALUES (3, 3, 'พัฒนาผลสัมฤทธิ์การเขียนโปรแกรมเบื้องต้นด้วยโปรแกรม Scratch', 'ผลสัมฤทธิ์รายวิชาวิทยาการคำนวณต่ำกว่าเป้าหมายที่สถานศึกษากำหนด โดยเฉพาะหน่วยการเขียนโปรแกรม', 'ใช้การจัดการเรียนรู้แบบ Pair Programming ร่วมกับโปรแกรม Scratch และการให้ข้อมูลย้อนกลับรายบุคคลทุกสัปดาห์', 'ผลสัมฤทธิ์เฉลี่ยของหน่วยการเขียนโปรแกรมเพิ่มขึ้นไม่น้อยกว่าร้อยละ 20 และนักเรียนผ่านเกณฑ์ร้อยละ 80 ขึ้นไป');
